function withLogging<Args extends unknown[], R>(fn: (...args: Args) => R): (...args: Args) => R {
  return (...args: Args): R => {
    console.log('->', fn.name, args);
    const out = fn(...args);                     // forward, types preserved
    console.log('<-', fn.name, out);
    return out;
  };
}
